import {
  PROMPT_MAX_LENGTH,
  isDuration,
  isEnergy,
  isMood,
  type DurationSeconds,
  type Energy,
  type Mood,
} from "./options";

const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export type GenerateRequest = {
  rhythmSlug: string;
  prompt: string;
  mood: Mood;
  energy: Energy;
  durationSeconds: DurationSeconds;
  // Generated by the form per deliberate submission and reused only when
  // resubmitting after a network failure, so retries dedupe but a new click
  // creates a new job.
  submissionId: string;
};

// Validates the POST /api/generate body. Returns null for anything malformed.
export function parseGenerateRequest(body: unknown): GenerateRequest | null {
  if (typeof body !== "object" || body === null) return null;
  const { rhythmSlug, prompt, mood, energy, durationSeconds, submissionId } = body as Record<
    string,
    unknown
  >;

  if (typeof rhythmSlug !== "string" || rhythmSlug.length === 0) return null;
  if (typeof prompt !== "string") return null;
  const trimmedPrompt = prompt.trim();
  if (trimmedPrompt.length === 0 || trimmedPrompt.length > PROMPT_MAX_LENGTH) return null;
  if (!isMood(mood) || !isEnergy(energy) || !isDuration(durationSeconds)) return null;
  if (typeof submissionId !== "string" || !UUID_PATTERN.test(submissionId)) return null;

  return { rhythmSlug, prompt: trimmedPrompt, mood, energy, durationSeconds, submissionId };
}
